"use client"

import * as React from "react"
import { OTPInput, OTPInputContext, REGEXP_ONLY_CHARS, REGEXP_ONLY_DIGITS, REGEXP_ONLY_DIGITS_AND_CHARS } from "input-otp"

import { Icon } from "@/components/ui/icon"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { otpCss, otpSlotRecipe } from "@/lib/ink/recipes/input-otp-ink"
import { cn } from "@/lib/utils"

const stripSeparators = (pasted: string): string => pasted.replace(/[\s\u2010-\u2015-]+/g, "")

const InvalidContext = React.createContext<{ invalid: boolean; disabled: boolean; touched: boolean }>({ invalid: false, disabled: false, touched: false })

function InputOTP({
  className,
  containerClassName,
  invalid,
  disabled,
  onChange,
  pasteTransformer = stripSeparators,
  ...props
}: React.ComponentProps<typeof OTPInput> & {
  containerClassName?: string
  invalid?: boolean
}) {
  const [touched, setTouched] = React.useState(false)
  const bad = !!invalid || props["aria-invalid"] === true || props["aria-invalid"] === "true"
  const value = React.useMemo(() => ({ invalid: bad, disabled: !!disabled, touched }), [bad, disabled, touched])
  return (
    <InvalidContext.Provider value={value}>
      <style href="ll-input-otp" precedence="low">
        {otpCss()}
      </style>
      <OTPInput
        data-slot="input-otp"
        data-touched={touched ? "" : undefined}
        aria-invalid={bad || undefined}
        disabled={disabled}
        pasteTransformer={pasteTransformer}
        containerClassName={cn("group/otp flex max-w-full flex-nowrap items-center gap-3 has-disabled:cursor-not-allowed", containerClassName)}
        className={cn("disabled:cursor-not-allowed", className)}
        onChange={(v) => {
          setTouched(true)
          onChange?.(v)
        }}
        {...props}
      />
    </InvalidContext.Provider>
  )
}

function InputOTPGroup({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="input-otp-group" className={cn("flex min-w-0 items-center gap-1.5 calm:gap-1", className)} {...props} />
}

function InputOTPSlot({
  index,
  className,
  seed,
  ref,
  ...props
}: React.ComponentProps<"div"> & {
  index: number
  seed?: string | number
}) {
  const inputOTPContext = React.useContext(OTPInputContext)
  const { invalid, disabled, touched } = React.useContext(InvalidContext)
  const { char, hasFakeCaret, isActive, placeholderChar } = inputOTPContext?.slots[index] ?? {}
  const { hostRef, hostProps, node } = useInk({
    recipe: otpSlotRecipe,
    params: { invalid, disabled, active: !!isActive, filled: !!char },
    kind: "field",
    seed,
    still: true,
  })
  return (
    <div
      data-slot="input-otp-slot"
      data-active={isActive}
      data-filled={char ? "true" : undefined}
      data-focus-visible={isActive ? "" : undefined}
      data-invalid={invalid ? "" : undefined}
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      className={cn(
        "relative isolate flex h-12 w-10 min-w-6 items-center justify-center font-script text-[1.75rem] leading-none font-semibold text-(--ll-input-ink) select-none compact:h-10 compact:w-9 calm:h-9 calm:w-8 calm:text-2xl",
        "data-[active=true]:z-10 forced-colors:border forced-colors:border-[CanvasText]",
        disabled && "text-pencil-text",
        className
      )}
      {...props}
    >
      {node}
      {char ? (
        <span key={char} className={cn(touched && "animate-pop")}>
          {char}
        </span>
      ) : (
        placeholderChar && <span className="text-(--ll-placeholder)">{placeholderChar}</span>
      )}
      {hasFakeCaret && (
        <span aria-hidden="true" className="pointer-events-none absolute inset-0 flex items-center justify-center">
          <span data-part="caret" />
        </span>
      )}
    </div>
  )
}

function InputOTPSeparator({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-slot="input-otp-separator" role="separator" className={cn("shrink-0 text-ink-soft", className)} {...props}>
      <Icon name="minus" size={20} />
    </div>
  )
}

export { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator, REGEXP_ONLY_CHARS, REGEXP_ONLY_DIGITS, REGEXP_ONLY_DIGITS_AND_CHARS }

import { wash } from '@/lib/ink/fills'
import { roundRectPoly, seg } from '@/lib/ink/geom'
import { Ink } from '@/lib/ink/builder'
import { defineRecipe } from '@/lib/ink/recipes'
import { clamp } from '@/lib/ink/rng'
import { box, dashedBox, focusRing } from '@/lib/ink/shapes'

export interface OtpSlotParams {
  invalid?: boolean
  disabled?: boolean
  active?: boolean
  filled?: boolean
}

export const otpSlotRecipe = defineRecipe<OtpSlotParams>({
  id: 'input-otp-slot',
  kind: 'field',
  layers: ['rest', 'invalid', 'disabled', 'focus'],
  pad: 12,
  draw(ink, { w, h }, { invalid, disabled, active, filled }, ctx) {
    const r = clamp(Math.min(w, h) * 0.1, 2, 4.5)
    const body = roundRectPoly(1.5, 1.5, w - 3, h - 3, r)
    if (active && !disabled) ink.layer('focus', () => focusRing(ink, 0, 0, w, h, { r, gap: 2.6 }))
    if (disabled) {
      ink.layer('disabled', () => {
        wash(ink, body, 'paper-shade', { alpha: 0.9, material: 'wash' })
        dashedBox(ink, 0, 0, w, h, { r, pen: 'pencil', opts: { color: 'pencil-mark' } })
      })
      return
    }
    if (invalid) {
      ink.layer('invalid', () => {
        ink.poly('under', body, 'slip', 0.7)
        box(ink, 0, 0, w, h, { pen: ctx.calm ? 'red.fine' : 'red', corner: r, style: ctx.calm ? 'loop' : 'two', ...(ctx.calm ? { stubs: false } : {}), ghost: false, opts: { width: ctx.calm ? 1.1 : 1.25 } })
      })
      return
    }
    ink.layer('rest', () => {
      ink.poly('under', body, 'slip', 0.7)
      if (ctx.calm) box(ink, 0, 0, w, h, { pen: 'pencil.fine', corner: r, style: 'loop', stubs: false, ghost: false })
      else box(ink, 0, 0, w, h, { pen: filled ? 'ink.fine' : 'pencil', corner: r, style: 'two', ghost: false, opts: { width: filled ? 1.05 : 1.15 } })
    })
  },
})

function caretTile(seed: string): string {
  const ink = new Ink(seed, { tier: 'lo', grain: false })
  ink.layer('rest', () => {
    const rng = ink.next('caret')
    const x = 4.5 + rng.range(-0.25, 0.25)
    ink.stroke(seg(x, 4, x + rng.range(-0.5, 0.5), 24, rng.range(-0.4, 0.4), 5), 'ink.brush', { color: 'current', width: 0.36, start: 'pool', end: 'pool', wobble: 0.5, simple: true })
    ink.stroke(seg(x - 3.3, 3.6 + rng.range(-0.2, 0.2), x + 3.3, 3.8 + rng.range(-0.2, 0.2), rng.range(-0.15, 0.15), 3), 'ink.brush', { color: 'current', width: 0.3, start: 'pool', end: 'pool', wobble: 0.3, simple: true })
    ink.stroke(seg(x - 3.3, 24.4 + rng.range(-0.2, 0.2), x + 3.3, 24.2 + rng.range(-0.2, 0.2), rng.range(-0.15, 0.15), 3), 'ink.brush', { color: 'current', width: 0.3, start: 'pool', end: 'pool', wobble: 0.3, simple: true })
  })
  const svg = ink.toSvg({ w: 9, h: 28, pad: 0 }).svg
  return `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 9 28" width="9" height="28">${svg}</svg>`)}")`
}

let cache: string | undefined

export function otpCss(): string {
  if (cache) return cache
  const tile = caretTile('otp|caret')
  cache =
    `[data-slot=input-otp-slot]{--ll-otp-caret:${tile}}` +
    `[data-slot=input-otp-slot] [data-part=caret]{display:block;width:9px;height:1.6rem;background:var(--ll-caret);-webkit-mask-image:var(--ll-otp-caret);mask-image:var(--ll-otp-caret);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;animation:ll-otp-blink 1.1s steps(1) infinite}` +
    `@keyframes ll-otp-blink{0%,55%{opacity:1}56%,100%{opacity:0}}` +
    `@media (prefers-reduced-motion:reduce){[data-slot=input-otp-slot] [data-part=caret]{animation:none}}` +
    `[data-motion=reduced] [data-slot=input-otp-slot] [data-part=caret]{animation:none}` +
    `@media (forced-colors:active){[data-slot=input-otp-slot] [data-part=caret]{background:CanvasText;-webkit-mask-image:none;mask-image:none;width:1px}[data-slot=input-otp-slot][data-active=true]{outline:3px solid Highlight}}`
  return cache
}
